/// <summary>
/// The answer of HSMobileOpsDeviceSetupService. ErrorCode is one of INVALID_REQUEST, CODE_UNKNOWN,
/// CODE_EXPIRED, CODE_USED_UP, DEVICE_LIMIT_REACHED, DEVICE_UNKNOWN or a license error code.
/// </summary>
[DataContractAttribute]
class HSMobileOpsDeviceSetupResponse
{
    boolean    success;
    str        errorCode;
    str        message;
    str        company;
    str        deviceName;
    int        activeDevices;
    int        maxDevices;
    str        publicKey;
    boolean    isActive;
    boolean    licenseValid;
    str        serverUtc;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('Company')]
public str parmCompany(str _value = company)
{
    company = _value;
    return company;
}

[DataMemberAttribute('DeviceName')]
public str parmDeviceName(str _value = deviceName)
{
    deviceName = _value;
    return deviceName;
}

[DataMemberAttribute('ActiveDevices')]
public int parmActiveDevices(int _value = activeDevices)
{
    activeDevices = _value;
    return activeDevices;
}

[DataMemberAttribute('MaxDevices')]
public int parmMaxDevices(int _value = maxDevices)
{
    maxDevices = _value;
    return maxDevices;
}

[DataMemberAttribute('PublicKey')]
public str parmPublicKey(str _value = publicKey)
{
    publicKey = _value;
    return publicKey;
}

[DataMemberAttribute('IsActive')]
public boolean parmIsActive(boolean _value = isActive)
{
    isActive = _value;
    return isActive;
}

[DataMemberAttribute('LicenseValid')]
public boolean parmLicenseValid(boolean _value = licenseValid)
{
    licenseValid = _value;
    return licenseValid;
}

[DataMemberAttribute('ServerUtc')]
public str parmServerUtc(str _value = serverUtc)
{
    serverUtc = _value;
    return serverUtc;
}
